import{_ as i,o as e,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-07-30 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-07-30 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-07-30T00:00:00.000Z","updated":"2019-08-03T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-30_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-07-30_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-07-30_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function a(_,l,n,r,c,p){return e(),o("div",null,[...l[0]||(l[0]=[t("<p>会议纪要</p><p>会议时间：[请填写具体时间] 会议地点：[请填写具体地点] 参会人员：[请填写参会人员名单]</p><p>一、会议关键细节</p><ol><li>会议因部分成员迟到而延迟开始。</li><li>多位成员汇报了各自的工作进展和遇到的问题。</li></ol><p>二、讨论的主要议题</p><ol><li>Ceph存储系统相关： <ul><li>成员汇报了在Ceph存储系统中遇到的14octuple问题，第一轮测试案例仍失败，但已取得进展。</li><li>讨论了基于meaning change实现lucid connection的replica优化方案。</li><li>分享了针对POSIX接口的修改和any store API的改进。</li><li>讨论了dirt class的支持修复，已提交PR。</li><li>分享了Ceph存储系统中object class DPI的实现和crimson的优化方案。</li></ul></li><li>视频会议字幕翻译及总结： <ul><li>分享了字幕翻译的实践经验，包括英译中和总结工作。</li><li>讨论了翻译过程中遇到的问题，以及提高翻译质量的方法。</li></ul></li><li>其他议题： <ul><li>汇报了back off功能的实现，以及避免频繁连接到manager的方法。</li><li>讨论了admin console interface的实现和UNIX domain sockets的支持。</li><li>分享了Protocol v2 looseness policy的实现和测试情况。</li><li>讨论了rocksDB在Ceph存储系统中的应用，以及与C-store的集成。</li></ul></li></ol><p>三、决定的事项</p><ol><li>针对Ceph存储系统： <ul><li>继续优化14octuple问题，并提交相关PR。</li><li>完善replica优化方案，并提交相关PR。</li><li>完善POSIX接口的修改，并提交相关PR。</li><li>修复dirt class问题，并提交相关PR。</li><li>优化object class DPI的实现，并提交相关PR。</li></ul></li><li>针对视频会议字幕翻译及总结： <ul><li>提高翻译质量，分享翻译经验。</li><li>完善翻译流程，确保翻译准确性和时效性。</li></ul></li><li>针对其他议题： <ul><li>完成back off功能的实现，并提交相关PR。</li><li>支持UNIX domain sockets，实现admin console interface。</li><li>完成Protocol v2 looseness policy的测试，并提交相关PR。</li><li>探索rocksDB在Ceph存储系统中的应用，并与C-store进行集成。</li></ul></li></ol><p>四、后续行动计划</p><ol><li>各成员按照决定的事项，继续推进各自的工作。</li><li>定期召开会议，汇报工作进展和讨论相关问题。</li><li>加强团队协作，共同推进Ceph存储系统和视频会议字幕翻译及总结工作。</li></ol>",10)])])}const m=i(s,[["render",a]]);export{d as __pageData,m as default};
